with src as (select jsonb_array_elements($j$[{"idea_id":"IDEA-00304","category_id":"CAT-0014","category_name":"Part Time Business Ideas","category_slug":"part-time-business-ideas","subcategory_id":"SUB-304","subcategory_name":"Part Time Freelance Copyediting For One Publication","subcategory_slug":"part-time-freelance-copyediting-one-publication","focus_keyword":"part time copyediting business","additional_keyword_1":"freelance editor limited hours side business","additional_keyword_2":"weekly publication proofreading service","business_description":"Copyedit a set number of articles each week for a single local newspaper or trade publication, working a fixed weekly hour block from a home computer around a day job. The customer is a small publication's editor who needs a second set of eyes but doesn't have budget for a full-time copyeditor. Money is a flat weekly or per-article rate, capped to an agreed volume. The hint: negotiate a hard weekly article cap upfront, since publications with breaking news can quietly expand your workload past what a part-time arrangement was meant to cover.","collection_id":"COL-DEFAULT","status":"completed","summary":"Charging $0.02 to $0.04 per word might sound like micro-pennies, but when your editing pace converts that math into an effective rate of $25 to $55 an hour, the financial picture changes completely. Running a part time copyediting business does not require juggling twenty fickle clients or bidding against thousands on gig platforms. Instead, you secure a single weekly publication proofreading service contract with one trade journal, local newspaper, or niche magazine that needs a reliable second set of eyes. You commit to a fixed block of evening or weekend hours from your home computer, reviewing a predictable batch of articles before press time. The secret to making a freelance editor limited hours side business work is capping your commitment upfront so breaking news does not bleed into your day job. It is predictable income built around one steady editorial relationship.","verdict":"This is an ideal side business for detail-oriented professionals who want steady, predictable income without managing multiple clients. Skip this model if you want passive scale or dislike working under tight, uncompromising press deadlines.","tier":"free","market_opportunity":"Small publications regularly run thin editorial teams that cannot justify a full-time staff copyeditor, yet they cannot afford embarrassing print errors. While standard freelance editors charge $25 to $80 an hour for generic proofreading, managing editors will gladly pay flat retainer arrangements to avoid management overhead. If you focus on high-stakes niches like medical, legal, or technical copyediting—which regularly command more than $85 an hour—the value proposition for a specialized publication becomes obvious. You fill a structural gap for publishers who need professional precision without paying full-time salaries.","target_customer":"Your primary target customer is the managing editor of an independent local newspaper, regional trade magazine, or niche industry newsletter. Right now, they are staying late on deadline nights doing their own proofreading after writing and layout, leading to missed typos and eye fatigue. They want one reliable person to handle a predictable weekly stack of stories without needing onboarding every single week.","how_you_make_money":"You charge either a flat weekly fee or a per-word rate capped at an agreed monthly volume. Standard rates run from $0.02 to $0.05 per word, or an hourly equivalent of $30 to $70 an hour for general press work. For specialist trade outlets in legal or medical fields, rates rise past $85 an hour, with specialist technical editing topping out around $120 an hour. One steady trade magazine sending 10,000 words a week at $0.03 per word generates a predictable $300 weekly revenue block.","startup_cost":"Startup costs are practically zero because you operate from an existing home computer using standard word-processing tools and style guides. Your main investment is the unpaid time spent directly pitching publication editors and reviewing their specific house style sheets.","income_potential":"Early income starts at $25 to $55 an hour on general per-word rate conversions, netting a few hundred dollars a month for a short block of work each weekend. With a specialized publication assignment in technical or legal fields, rates reach $85 to $120 an hour, capping out around $500 to $1,200 monthly per publication based on your strict hour limit.","competition_edge":"Most freelancers pitch broad services to hundreds of clients and spend half their week chasing invoices and writing proposals. Your edge comes from total single-client dedication and strict boundaries: you work for one publication at a time with a hard weekly article cap negotiated upfront. By emphasizing your domain focus over raw years of experience, you prove that specialism sets the rate rather than general seniority.","time_to_first_customer":"Landing your first publication contract usually takes 2 to 4 weeks of direct outreach to regional editors. Because publications run on tight weekly deadlines, an editor who loses an assistant can hire you within days of your pitch.","trend_score":74,"pros_json":["Predictable single-client invoicing eliminates constant sales outreach and pitch fatigue.","Effective per-word rates of $0.02 to $0.04 convert into strong hourly yields between $25 and $55 an hour.","High-level subject specialization in technical or legal fields drives rates over $85 an hour without requiring decades of experience."],"cons_json":["Breaking news cycles can pressure your negotiated boundaries if you fail to enforce article caps strictly.","Income is strictly capped by the limited hours you can spare around your day job.","Publication budget cuts or ownership changes can suddenly eliminate your single anchor client."],"getting_started_steps":["Select a specific niche domain, such as regional trade news, legal journals, or medical updates.","Identify 15 to 20 local newspapers or specialized publications that publish on a strict weekly schedule.","Audit recent issues of target publications to spot repeated stylistic errors or layout typos.","Pitch managing editors directly, offering a fixed weekly proofreading block for a set batch of articles.","Negotiate a firm contract with a hard weekly article cap to prevent breaking news scope creep.","Establish a streamlined file delivery workflow using standard redline and track-changes conventions."],"tools_needed":["Home computer with reliable high-speed internet connection","Standard word processing software with track-changes functionality","Industry-standard digital dictionary and style manual access","Simple time-tracking application to monitor effective hourly rates","PDF annotation software for page-proof checking"],"faq_json":[{"q":"How do I avoid working double hours when breaking news hits?","a":"Negotiate a hard weekly article cap or word-count ceiling directly in your initial agreement. If the publication needs extra coverage during major news cycles, bill any overage beyond the cap at standard hourly rates of $30 to $70 an hour."},{"q":"Can I command high rates if I do not have twenty years of journalism experience?","a":"Yes, because the niche matters far more than your years served. While standard editing starts around $25 to $55 an hour effective rate, specialized technical or legal editing regularly commands more than $85 to $120 an hour regardless of career duration."},{"q":"How do I balance deadline turnarounds with my full-time day job?","a":"Lock in a single weekend or evening window that aligns with the publisher prepress cycle. Ensure your contract specifies that files delivered after your agreed evening window shift to the next morning review block."}]},{"idea_id":"IDEA-00306","category_id":"CAT-0014","category_name":"Part Time Business Ideas","category_slug":"part-time-business-ideas","subcategory_id":"SUB-306","subcategory_name":"Part Time Freelance Illustration For One Agency","subcategory_slug":"part-time-freelance-illustration-one-agency","focus_keyword":"part time illustration business","additional_keyword_1":"freelance illustrator retained hours side business","additional_keyword_2":"limited capacity design service","business_description":"Take on a fixed number of illustration projects per month for a single small design agency, working from a home tablet setup around a day job, with a firm monthly project cap agreed in advance. The customer is a small agency that needs overflow illustration capacity but not a full-time hire. Money is a flat per-project fee, capped to the agreed monthly volume. The hint: turn down any project past the agreed cap rather than squeezing it in, since consistently overdelivering past the agreed limit is what trains a client to expect unlimited part-time capacity for the same fee.","collection_id":"COL-DEFAULT","status":"completed","summary":"Most artists assume the drawing fee is the whole fee when building a part time illustration business. In reality, the licence is where the money hides, and treating artwork like bulk labor is how solo creators burn out around a day job. This business model relies on a limited capacity design service delivered exclusively to one small agency needing overflow art support. Instead of chasing dozens of clients, you contract for a fixed monthly deliverable volume with a firm project cap agreed in advance. A freelance illustrator retained hours side business works because the agency gets dependable creative output without a full-time salary. The essential discipline is turning down any request past the cap, keeping your schedule intact and protecting your creative energy.","verdict":"This micro-niche is ideal for skilled artists seeking predictable side income without managing multiple client relationships. Skip it if you struggle to set firm boundaries or want to scale an agency of your own.","tier":"free","market_opportunity":"Boutique agencies regularly land client work requiring specialized art but cannot justify taking on a full-time internal illustrator. Market rates span broadly, with junior tasks starting near $20 to $40 an hour while senior or specialist work reaches $75 to $150 and up. Agencies struggle to find dependable partners who understand legal usage rights and respect project limits. Offering dedicated overflow support to a single client fills this structural gap without the overhead of pitching multiple accounts.","target_customer":"The primary customer is an owner or creative director at a small design agency that handles branding, web, or print campaigns. They currently rely on generic freelance platforms, suffering through inconsistent quality, missed deadlines, and vague intellectual property terms. They need a steady, rights-aware partner who delivers high-grade assets on schedule. Partnering with one dedicated artist under a fixed monthly cap eliminates their staffing bottlenecks.","how_you_make_money":"You charge a flat per-project fee capped to an agreed monthly volume, using your skill tier to set baseline values. Mid-level illustration commands $50 to $100 an hour, while senior work reaches $75 to $150 and up, translating into project fees from $150 to $5,000 or more. Spot illustrations generally command $50 to $500 per piece, whereas commercial advertising work can exceed $10,000 once usage rights are incorporated. Because licensing usage rights is a second negotiation separate from the drawing fee, your earnings per asset increase significantly when campaigns scale.","startup_cost":"Startup costs are near zero assuming you already own a tablet setup and digital illustration software. Minimal expenses go toward drafting standard legal agreements that split creation fees from licensing terms. No physical studio space or inventory is required.","income_potential":"Early earnings for junior-level output sit around $20 to $40 an hour, or $50 to $500 for smaller spot illustrations. With mid-level to senior expertise, hourly benchmarks shift to $50 or $150 and up, while commercial advertising work can exceed $10,000 once broad usage rights are tallied. Income remains intentionally bounded by your monthly project cap to protect your primary job.","competition_edge":"Standard freelancers compete by taking every piece of work that hits their inbox, leading to missed deadlines and scope creep. Your structural advantage comes from strict artificial scarcity: servicing only one agency with a firm cap on deliverables. Separating the creation fee from secondary licensing rights establishes professional authority. Enforcing your monthly limit trains the client to value your reserved capacity rather than treating you like an on-demand resource.","time_to_first_customer":"Landing your single agency partner typically takes a few weeks of targeted direct outreach. Because you only need one client to fill your limited bandwidth, the sales cycle is short.","trend_score":74,"pros_json":["Single-client focus eliminates constant marketing and client acquisition work.","Licensing rights provide additional revenue beyond simple hourly labor.","Firm monthly caps protect your day job from unexpected burnout."],"cons_json":["Overall income is strictly capped by your limited part-time capacity.","Losing your single agency client drops your side revenue to zero immediately.","Requires strong interpersonal boundaries to decline out-of-scope requests."],"getting_started_steps":["Prepare your home tablet setup and assemble a focused portfolio of commercial artwork.","Draft a clear pricing sheet that explicitly separates initial drawing fees from secondary licensing rights.","Compile a targeted list of small design agencies that lack in-house illustration staff.","Pitch agency owners directly on a limited overflow partnership capped to a fixed monthly deliverable limit.","Sign a contract defining project boundaries, revision limits, and payment schedules.","Deliver the first month of illustrations and strictly enforce the agreed project cap."],"tools_needed":["Digital drawing tablet and stylus setup","Vector and raster graphic design software","Standard freelance contract template covering licensing rights","Invoicing and payment collection tool","Secure file transfer and cloud storage account"],"faq_json":[{"q":"What happens if the agency requests work beyond the agreed cap?","a":"Decline the additional project or push it to the following month's allocation. Consistently overdelivering past the agreed limit trains the client to expect unlimited capacity for a fixed fee."},{"q":"How do I price drawing fees versus licensing rights?","a":"Treat usage rights as a second negotiation rather than bundling them into the initial creation cost. The drawing fee covers the labor and file creation, while licensing charges reflect how broadly the agency or their client will use the art."},{"q":"What rate should I set when pitching an agency?","a":"Base your project estimates on your experience tier. Junior work sits near $20 to $40 an hour, mid-level ranges from $50 to $100, and senior or specialist work commands $75 to $150 and up."}]},{"idea_id":"IDEA-00308","category_id":"CAT-0014","category_name":"Part Time Business Ideas","category_slug":"part-time-business-ideas","subcategory_id":"SUB-308","subcategory_name":"Part Time Freelance Grant Report Writing For One Nonprofit","subcategory_slug":"part-time-freelance-grant-report-writing-one-nonprofit","focus_keyword":"part time grant report writing business","additional_keyword_1":"nonprofit reporting side business limited hours","additional_keyword_2":"freelance grant compliance writing service","business_description":"Write the required progress and outcome reports for a single small nonprofit's existing grants on a fixed part-time schedule, working from the nonprofit's program data and a monthly check-in call. The customer is a small nonprofit director who has grant funding but no staff time to write the mandatory follow-up reports funders require. Money is a flat monthly retainer scaled to the agreed report volume. The hint: build a reusable report template matched to that specific funder's format, since matching their exact required structure is what gets reports approved without revision requests eating into your capped hours.","collection_id":"COL-DEFAULT","status":"completed","summary":"Small nonprofit directors will inevitably ask if you can write for a percentage of the grant money won, but taking a contingency fee is treated as unethical in the profession and is prohibited outright for federal funds. A sustainable part time grant report writing business operates on a completely different premise: handling post-award progress and outcome reporting for a single organization on a fixed schedule. Instead of chasing proposal volume, you focus entirely on keeping one nonprofit compliant with their existing grantors. You take raw program data, host one monthly check-in call, and format reports using reusable templates tailored to specific funder guidelines. It is an ideal nonprofit reporting side business limited hours setup for experienced writers who want predictable, low-friction retainer work without proposal-writing chaos.","verdict":"This micro-niche is ideal for experienced writers or nonprofit veterans looking for steady retainer income on a strict, limited-hours schedule. Skip it if you want to run a high-volume agency or rely on commission-style success fees, which are strictly prohibited in professional grant management.","tier":"free","market_opportunity":"Small nonprofits frequently win grant funding but lack the internal staff hours required to assemble mandatory follow-up reports. While full foundation proposals run $1,500 to $5,000 and federal applications demand $5,000 to $15,000 or more, post-award compliance is often neglected until deadline panic sets in. Operating a freelance grant compliance writing service fills this precise operational gap by turning chaotic program outcomes into funder-ready documentation. By maintaining existing funding relationships rather than hunting new leads, you provide an essential service with stable demand.","target_customer":"Your target customer is an executive director at a small nonprofit who successfully lands grants but is overwhelmed by administrative follow-up. Today, they scramble late at night to aggregate participant counts and financial breakdowns, risking delayed funding disbursements or damaged funder trust. They do not need a full-time grant director; they need a reliable specialist to keep current grantors informed and happy. They hire you to transform raw internal notes into clean reports that get approved without constant back-and-forth revisions.","how_you_make_money":"You charge a flat monthly retainer tied to expected report volume, giving the nonprofit a fixed budget and protecting your own schedule. While standard industry retainers of $2,000 to $6,000 typically cover one to three proposals, your report-focused retainer sits at a predictable baseline for compliance work. Freelance grant writers generally bill between $30 and $150 an hour, with mid-level writers around $75. However, if you are a genuine subject-matter expert in the nonprofit's specific sub-field, you can command two to three times generalist rates for the same word count.","startup_cost":"Startup costs are virtually zero because the business requires only standard word processing tools, cloud storage, and basic video communication software. You do not need dedicated office space or expensive enterprise software to launch. Your main upfront investment is building standardized, reusable report templates matched to common funder formats.","income_potential":"Income reflects professional industry rates, where generalist mid-level writers average around $75 an hour and senior practitioners reach $95 to $150 an hour. Positioning yourself as a niche subject-matter expert allows you to charge two to three times generalist rates while maintaining your workload. Working with a single client caps total earnings, but preserves strict part-time boundaries.","competition_edge":"Most freelance grant writers focus exclusively on pitching new proposals, leaving mandatory progress reporting largely ignored. Generalist writers often spend extra hours trying to understand technical program details, driving up cost and back-and-forth edits. Your edge comes from creating custom templates upfront that match each funder's exact structure, ensuring reports are approved on the first pass without revision requests eating into your capped hours.","time_to_first_customer":"Securing your first nonprofit client typically takes two to four weeks of direct outreach to executive directors. Because you are solving an immediate compliance burden rather than selling speculative proposal work, decision cycles are relatively fast.","trend_score":74,"pros_json":["Adhering to ethical flat-rate pricing protects your professional reputation and keeps you compliant with federal funding rules.","Predictable retainer income without the high rejection rates and stress associated with writing new proposals.","Deep subject-matter expertise allows you to bill two to three times generalist rates while keeping hours capped."],"cons_json":["Strict prohibition against contingency fees means you cannot earn a percentage of large grant awards.","Dependence on internal nonprofit staff to deliver raw program numbers on time for reporting deadlines.","Limiting your roster to one nonprofit puts an absolute ceiling on your maximum side business income."],"getting_started_steps":["Establish a clear ethics policy that rejects contingency or success-fee pricing outright.","Identify small local or cause-specific nonprofits with active grant funding but small administrative teams.","Offer executive directors a flat monthly retainer focused exclusively on post-award reporting compliance.","Review the client's current grant agreements, deadline calendars, and required funder reporting guidelines.","Set up a recurring monthly check-in call and simple data collection sheet for program staff.","Build reusable report templates designed to fit each funder's specific formatting requirements.","Submit initial progress reports early to establish trust and eliminate mandatory revision loops."],"tools_needed":["Standard word processing and spreadsheet software","Secure cloud folder system for client data and compliance files","Video calling platform for monthly client check-in meetings","Digital calendar or task management tool for deadline tracking"],"faq_json":[{"q":"Can I charge a percentage of the grant money as my fee?","a":"No. Contingency or success-fee pricing is treated as unethical in the grant writing profession and is prohibited outright for federal funds. You must always charge flat project fees, hourly rates, or structured retainers."},{"q":"What do freelance grant writers usually charge for different types of work?","a":"Hourly rates range from $30 to $150 an hour, with senior writers at $95 to $150. Project fees scale by complexity: foundation letters of inquiry run $400 to $1,200, full foundation proposals run $1,500 to $5,000, and federal applications range from $5,000 to $15,000 or more."},{"q":"How can I increase my rate without taking on more hours?","a":"Focus on becoming a genuine subject-matter expert in a specific domain. Industry benchmarks show that subject-matter experts command two to three times generalist rates for the exact same word count."}]}]$j$::jsonb) as r)
insert into public.ideas (idea_id, category_id, category_name, category_slug, subcategory_id, subcategory_name, subcategory_slug, focus_keyword, additional_keyword_1, additional_keyword_2, business_description, collection_id, status, title, summary, verdict, tier, slug, seo_title, meta_description, market_opportunity, target_customer, how_you_make_money, startup_cost, income_potential, competition_edge, time_to_first_customer, trend_score, tags, pros_json, cons_json, getting_started_steps, tools_needed, faq_json, external_links, internal_link_anchors, research_facts)
select nullif(r->>'idea_id',''), nullif(r->>'category_id',''), nullif(r->>'category_name',''), nullif(r->>'category_slug',''), nullif(r->>'subcategory_id',''), nullif(r->>'subcategory_name',''), nullif(r->>'subcategory_slug',''), nullif(r->>'focus_keyword',''), nullif(r->>'additional_keyword_1',''), nullif(r->>'additional_keyword_2',''), nullif(r->>'business_description',''), nullif(r->>'collection_id',''), nullif(r->>'status',''), coalesce(nullif(r->>'title',''), ir.title), nullif(r->>'summary',''), nullif(r->>'verdict',''), nullif(r->>'tier',''), coalesce(nullif(r->>'slug',''), ir.slug), coalesce(nullif(r->>'seo_title',''), ir.seo_title), coalesce(nullif(r->>'meta_description',''), ir.meta_description), nullif(r->>'market_opportunity',''), nullif(r->>'target_customer',''), nullif(r->>'how_you_make_money',''), nullif(r->>'startup_cost',''), nullif(r->>'income_potential',''), nullif(r->>'competition_edge',''), nullif(r->>'time_to_first_customer',''), (r->>'trend_score')::int, coalesce(r->'tags', ir.tags), r->'pros_json', r->'cons_json', r->'getting_started_steps', r->'tools_needed', r->'faq_json', coalesce(r->'external_links', ir.external_links), coalesce(r->'internal_link_anchors', ir.internal_link_anchors), coalesce(r->'research_facts', ir.research_facts)
from src left join public.idea_research ir on ir.idea_id = src.r->>'idea_id'
on conflict (idea_id) do nothing;
with src as (select jsonb_array_elements($j$[{"idea_id":"IDEA-00309","category_id":"CAT-0014","category_name":"Part Time Business Ideas","category_slug":"part-time-business-ideas","subcategory_id":"SUB-309","subcategory_name":"Part Time Evening Guitar Lesson Teaching","subcategory_slug":"part-time-evening-guitar-lesson-teaching","focus_keyword":"part time guitar teaching business","additional_keyword_1":"evening music lessons side business","additional_keyword_2":"weeknight guitar tutoring service","business_description":"Teach guitar lessons two or three weeknights from a home practice room using a personal amp and a small set of loaner guitars for beginners, scheduled around a full-time day job. The customer is an adult beginner or teenager wanting structured lessons without a music school's overhead pricing. Money is a flat per-lesson or monthly package fee. The hint: keep a short waitlist rather than overbooking evenings, since a capped, reliable schedule is what actually protects lesson quality on a part-time teaching load.","collection_id":"COL-DEFAULT","status":"completed","summary":"Guitar lessons sit lower than piano rates—topping out around $45 to $70 an hour for one-to-one instruction, compared to the $50 to $100 standard for piano. If you run a part time guitar teaching business, that pricing ceiling means you cannot rely on sheer student volume, especially when adult beginners routinely drop off once the initial novelty fades and chord transitions get tough. The model here is simple and deliberate: host single students two or three weeknights in your home practice room using your existing amp and a small set of loaner guitars. Instead of packing your evenings until your patience burns out, you maintain a structured weeknight guitar tutoring service with flat per-lesson or monthly package billing and an intentional cap on your schedule. Keeping a short waitlist protects your energy, keeps lesson quality sharp after your day job, and ensures your revenue remains predictable.","verdict":"This micro-niche is ideal for experienced guitarists who want a grounded evening music lessons side business without commercial studio overhead. If you need uncapped scalable income or dislike repetitive foundational teaching, look toward alternative business models.","tier":"free","market_opportunity":"While private music lessons average $40 to $90 an hour nationally, standard music schools stack overhead fees onto that baseline pricing. Students paying $45 to $70 an hour for one-to-one guitar instruction often struggle to find weeknight slots that fit around full-time work without paying studio markups. Building an evening music lessons side business fills this gap by giving adult beginners and teenagers dedicated, undistracted access to a working guitarist's practice room.","target_customer":"Your core clients are adult beginners looking for structured guitar instruction after work and parents of teenagers wanting personal attention without traditional music school contracts. They are tired of self-directed online video tutorials that leave them stuck on basic mechanics, but they do not want to commute across town during peak dinner hours. They choose your service because it provides consistent weeknight timeslots, direct feedback, and a relaxed home practice room setup.","how_you_make_money":"You collect income through flat per-lesson rates or monthly package fees for dedicated weekly slots. Rates for standard sixty-minute sessions anchor within the realistic range of $45 to $70 an hour for one-to-one guitar tuition, while thirty-minute beginner options band clearly from $30 to $50 per lesson. Charging upfront monthly retainers keeps income stable when pupil attendance wobbles or when early momentum wanes.","startup_cost":"Startup costs are near zero if you already play. You rely on your existing guitar setup, a personal practice amp, and a couple of reliable loaner instruments for beginners who do not own gear yet. Beyond minor acoustic room adjustments and printed lesson sheets, upfront cash requirements remain minimal.","income_potential":"Because guitar instruction commands $45 to $70 an hour for one-to-one sessions, your earning cap depends strictly on how many evening hours you allocate. Teaching two or three weeknights with a small cohort yields consistent part-time cash without risking burnout, while thirty-minute beginner slots priced at $30 to $50 provide steady baseline income.","competition_edge":"Commercial music studios overload their evening calendars, leading to fatigued instructors and rushed turnarounds between sessions. Your structural edge is strict schedule control and a tight cap on evening slots. By maintaining a short waitlist rather than overbooking your post-work hours, your part time guitar teaching business protects lesson quality and keeps student retention high even as novelty wears off.","time_to_first_customer":"With targeted neighborhood outreach and personal referrals, securing your first paying weeknight student typically takes a short period of focused local networking.","trend_score":74,"pros_json":["Low financial barrier to entry using your existing instruments and home practice room","Flexible schedule easily restricted to two or three weeknights around your day job","Predictable recurring cash flow when using upfront monthly package fees"],"cons_json":["Guitar rates sit lower than piano, topping out near $45 to $70 an hour for one-to-one tuition","High initial pupil drop-off rates as beginners encounter finger discomfort and practice fatigue","Hard limit on income since your available teaching hours are capped by evening availability"],"getting_started_steps":["Audit your home practice room to ensure adequate lighting, seating, and sound isolation for evening sessions.","Set up a small inventory of loaner guitars so absolute beginners can take their first lesson before buying gear.","Define your fixed weeknight availability, capping instruction to two or three evenings to avoid day-job burnout.","Establish flat per-lesson or monthly package pricing within the local $45 to $70 hourly range for guitar instruction.","Draft a simple lesson policy detailing cancellation windows and monthly package payment terms.","Distribute local notices targeting neighborhood families and working adults seeking weeknight music tutoring."],"tools_needed":["Personal guitar amplifier and instrument cables","Loaner acoustic and electric guitars for beginner trial sessions","Dedicated practice room seating and music stands","Digital scheduling calendar for post-work timeslots","Standard payment processing app or simple invoice software"],"faq_json":[{"q":"How do I handle students who quit when guitar practice gets difficult?","a":"Pupil drop-off is normal once finger soreness sets in and initial novelty fades. Frame lessons around small achievable song milestones and keep a short waitlist to quickly fill open weeknight slots."},{"q":"Should I travel to students' homes to charge higher rates?","a":"While teaching in the home commands $70 to $100 an hour compared to $60 to $90 in a studio, traveling consumes valuable evening transit time after your day job. Teaching from your home practice room keeps your evening schedule tight and manageable."},{"q":"What length should beginner guitar lessons be?","a":"Thirty-minute lessons band clearly between $30 to $50 for beginner to intermediate students, making them ideal for younger pupils or busy adults with limited post-work focus."}]},{"idea_id":"IDEA-00311","category_id":"CAT-0014","category_name":"Part Time Business Ideas","category_slug":"part-time-business-ideas","subcategory_id":"SUB-311","subcategory_name":"Part Time Freelance Video Editing For One YouTube Channel","subcategory_slug":"part-time-freelance-video-editing-one-youtube-channel","focus_keyword":"part time video editing business","additional_keyword_1":"freelance youtube editor limited hours side business","additional_keyword_2":"weekly channel editing retainer service","business_description":"Edit a fixed number of videos per week for a single YouTube creator using free editing software from a home computer, working an agreed weekly hour block around a day job. The customer is a growing creator who needs consistent editing help but not a full-time hire yet. Money is a flat weekly or per-video retainer, capped to the agreed volume. The hint: lock in the exact turnaround day each week, since a creator's whole upload schedule depends on that single predictable delivery date more than on any other part of the arrangement.","collection_id":"COL-DEFAULT","status":"completed","summary":"It is 11:15 PM on a Sunday night, your timeline is render-ready, and a creator half a world away is waiting to queue their Monday morning upload. That render progress bar is the real clock governing this part time video editing business. Instead of chasing dozens of one-off gig requests on saturated marketplaces, you anchor your side hours around a single growing YouTube creator who needs reliable cuts but cannot afford a full-time staff hire. You operate as a weekly channel editing retainer service, turning raw footage into finished uploads inside a predictable weekly hour block worked around your day job. Using free software from your home computer, you keep overhead at zero while taking over the editing burden. It is a structured freelance youtube editor limited hours side business built on one core promise: hitting the exact turnaround date every single week.","verdict":"A practical, low-overhead side business for organized editors who want steady weekly income from a single client rather than chasing endless one-off gigs. Skip it if you cannot commit to rigid weekly delivery dates alongside your primary job.","tier":"free","market_opportunity":"Growing YouTube creators often reach a point where editing their own videos eats up twenty hours a week, yet hiring a full-time video editor is financially out of reach. Industry rate data shows freelance video editors charge between $25 and $150 an hour, with mid-level work averaging about $58 an hour. A single-channel retainer sits perfectly in this gap, providing predictable editing capacity for the creator while securing steady side income for you.","target_customer":"Your target client is a solo YouTube creator whose channel is generating income but who is drowning in post-production work. They currently edit their own footage late at night or rely on unreliable gig freelancers who miss deadlines right before scheduled uploads. They are looking for one dependable editor who understands their style and guarantees a fixed delivery day every week.","how_you_make_money":"You charge a flat weekly or per-video retainer capped to an agreed volume of footage and working hours. Entry-level freelance video editors typically bill $20 to $45 an hour, while mid-level editors charge $45 to $85 an hour, with a median remote freelance rate near $60 an hour (within a $47 to $77 band). Pricing your single-channel package around these validated rate bands gives the creator a fixed monthly cost and gives you guaranteed pay without scope creep.","startup_cost":"Startup costs are near zero if you already own a functional desktop or laptop computer. You operate the service using free professional video editing software and free cloud file transfer tools, requiring no paid software subscriptions to launch.","income_potential":"At entry rates of $20 to $45 an hour, editing five to ten hours a week for one channel brings in consistent baseline side income. As your pacing sharpens into mid-level quality where rates sit near $58 an hour, your monthly retainer grows accordingly, while senior editors charging $85 to $150 and above illustrate the long-term ceiling if you refine specialist skills.","competition_edge":"Most marketplace editors view video cuts as quick one-off jobs, forcing creators to repeatedly explain their branding and pray their editor meets the deadline. Your advantage comes from dedicating your available side hours entirely to one channel and locking in an exact, non-negotiable turnaround day. Because a creator's upload consistency drives their channel growth, your calendar reliability matters far more than flashy special effects.","time_to_first_customer":"Securing your single channel retainer typically takes two to four weeks of direct, direct-to-creator outreach.","trend_score":76,"pros_json":["Provides predictable weekly retainer income without the constant hustle of pitching new clients every few days.","Requires zero software capital outlay by leveraging free editing tools on existing computer hardware.","Fits cleanly into off-duty hours because your workload is strictly capped to one client's schedule."],"cons_json":["Your earnings are capped by the single channel's weekly volume unless you raise your rates over time.","Missing a turnaround date breaks channel trust instantly because creator upload algorithms depend on strict schedules.","Revenue drops to zero if the channel owner pauses production or cancels the retainer arrangement."],"getting_started_steps":["Assemble a brief sample reel showcasing clean pacing, basic graphics, and audio balancing built with free software.","Identify ten active YouTube channels in a single niche that post weekly but show unpolished editing.","Reach out to channel owners with a concise pitch offering a fixed weekly turnaround schedule for a flat retainer trial.","Agree on capped raw footage lengths, standard revision limits, and explicit weekly delivery dates.","Set up a shared cloud storage folder structure for seamless raw video file transfers.","Deliver your first three weekly cuts ahead of the agreed deadline to cement operational trust."],"tools_needed":["Desktop or laptop computer capable of handling high-definition video files","Free professional video editing software","Cloud storage account for receiving large raw footage files and delivering exports","High-speed internet connection for stable file transfers"],"faq_json":[{"q":"Do I need expensive editing software to start this side business?","a":"No. You can edit full YouTube videos using completely free, professional-grade editing software installed on your current computer without paying monthly subscription fees."},{"q":"How do I make sure the creator does not demand endless edits?","a":"Define your agreement clearly up front: set a capped block of weekly hours based on standard rates like $20 to $45 an hour for entry work or $45 to $85 for mid-level work, and limit revisions to one structural pass."},{"q":"Can I really run this around a standard full-time day job?","a":"Yes. Because you work with only one channel and lock in fixed turnaround windows, you can schedule your editing hours reliably during predictable evening or weekend blocks."}]},{"idea_id":"IDEA-00313","category_id":"CAT-0014","category_name":"Part Time Business Ideas","category_slug":"part-time-business-ideas","subcategory_id":"SUB-313","subcategory_name":"Part Time Freelance Podcast Editing For One Weekly Show","subcategory_slug":"part-time-freelance-podcast-editing-one-weekly-show","focus_keyword":"part time podcast editing business","additional_keyword_1":"freelance podcast editor limited hours side business","additional_keyword_2":"weekly show editing retainer service","business_description":"Edit one weekly podcast episode for a single host using free editing software from a home computer, working a fixed evening block around a day job. The customer is a podcast host who records consistently but needs reliable post-production without a full-time hire. Money is a flat per-episode fee, billed weekly for the standing show. The hint: block the same evening every week for this one show, since a dedicated fixed slot is what keeps a single-client part-time arrangement sustainable alongside a day job long term.","collection_id":"COL-DEFAULT","status":"completed","summary":"Why are you still tracking hourly logs when podcasters prefer paying a flat per-episode rate? Operating a part time podcast editing business around a day job only stays manageable when you bound your commitment to a single weekly show. Instead of juggling six volatile clients, you take one host who records every week and reserve one predictable evening block on your calendar to deliver their audio. Most independent podcasters pay $100 to $300 an episode for professional audio editing, making a single client a steady income stream for a few hours of focused work. Starting at the budget tier of $50 to $150 an episode for basic cleanup lets you build speed on free editing software from your home computer. Once trust is established, the real financial growth comes from stepping up to full-service production—adding show notes, publishing, and promo clips—which expands the ticket to $400 to $1,000 or more per episode.","verdict":"This micro-niche is ideal for detail-oriented professionals who want a reliable, single-client side business built around one predictable evening block per week. Skip it if you want passive income or dislike sticking to rigid weekly submission deadlines.","tier":"free","market_opportunity":"Thousands of niche podcast hosts produce audio regularly but stall at the post-production stage. While generic freelancers quote $40 to $120 an hour with unpredictable invoices, creators want reliable per-episode costs. Standard interview formats command $150 to $500 per episode, giving you a strong financial return on a weekly show editing retainer service without ballooning your schedule.","target_customer":"Your target client is a solo creator or consultant who publishes a weekly show but lacks the time or interest for post-production audio cleanup. Today, they either waste late nights editing track cuts themselves or rely on unvetted gig workers who miss publishing schedules. They need a freelance podcast editor limited hours side business partner who takes the raw recording on a set day and delivers clean audio ready to air.","how_you_make_money":"You charge a flat per-episode rate billed weekly for one standing show. Basic cleanup and simple cuts start at budget rates of $50 to $150 per episode, while standard work sits in the common professional band of $150 to $350 per episode. Over time, expanding into full-service production with show notes, clips, and publishing moves the rate into the $400 to $1,000 or more per episode tier for the same account.","startup_cost":"Startup costs are near zero if you already own a functional home computer. You run the operation using free editing software and basic monitoring headphones, avoiding paid software subscriptions or specialized studio gear until your revenue justifies it.","income_potential":"Handling simple audio cleanup for one weekly show at $100 to $300 per episode earns $400 to $1,200 per month from a single dedicated evening block. Upselling that same client to full-service production can elevate monthly revenue to $1,600 to $4,000 or more without adding extra shows.","competition_edge":"Most freelance audio editors attempt to scale by onboarding as many clients as possible, leading to missed deadlines and rushed work. Your edge is hyper-focused reliability: running a weekly show editing retainer service dedicated exclusively to one host. By blocking the exact same evening slot every week, you eliminate turn-around risk and build an indispensable working relationship.","time_to_first_customer":"By reaching out directly to active self-editing hosts, you can secure your single weekly client within two to four weeks.","trend_score":76,"pros_json":["Zero financial risk to launch using your existing home computer and free software.","Highly manageable side business structure built around blocking a single recurring evening slot.","Clear upsell path into full-service production earning $400 to $1,000 or more per episode."],"cons_json":["Revenue is directly capped unless you expand service scope or take on more working hours.","Total client dependency means income drops if the host pauses or cancels their show.","Tight weekly turnarounds require strict discipline after your regular day job."],"getting_started_steps":["Install free audio editing software on your home computer and practice basic track alignment and noise reduction.","Designate one specific evening block every week strictly reserved for audio post-production around your day job.","Set up a simple intake workflow using a shared cloud folder and flat-rate weekly billing.","Reach out directly to self-edited podcasters who release standard interview format episodes on a strict weekly cadence.","Offer a paid test edit on one episode at a budget-tier rate of $50 to $150 to prove turnaround speed.","Once established, pitch an upgraded full-service production package including show notes and promotional clips to increase income per episode."],"tools_needed":["Existing home computer with sufficient memory for audio rendering","Free open-source audio editing software","Monitoring headphones for accurate audio cleanup","Shared cloud storage folder for episode file delivery","Invoicing and automated payment collection platform"],"faq_json":[{"q":"Should I charge hourly or per episode for podcast editing?","a":"Podcast editors charge roughly $40 to $120 an hour, but flat per-episode pricing is far better for a part-time workflow. Charging within the common professional band of $150 to $350 per episode rewards your efficiency and gives the client a fixed cost."},{"q":"Do I need expensive software to edit a professional podcast?","a":"No. You can deliver excellent basic cleanup and simple cuts at $50 to $150 per episode using free editing software on a standard home computer."},{"q":"How can I increase revenue without taking on a second client?","a":"Move up the service ladder from basic audio editing to full-service production. Adding show notes, episode publishing, and social clips increases your per-episode rate to $400 to $1,000 or more while working with the exact same host."}]}]$j$::jsonb) as r)
insert into public.ideas (idea_id, category_id, category_name, category_slug, subcategory_id, subcategory_name, subcategory_slug, focus_keyword, additional_keyword_1, additional_keyword_2, business_description, collection_id, status, title, summary, verdict, tier, slug, seo_title, meta_description, market_opportunity, target_customer, how_you_make_money, startup_cost, income_potential, competition_edge, time_to_first_customer, trend_score, tags, pros_json, cons_json, getting_started_steps, tools_needed, faq_json, external_links, internal_link_anchors, research_facts)
select nullif(r->>'idea_id',''), nullif(r->>'category_id',''), nullif(r->>'category_name',''), nullif(r->>'category_slug',''), nullif(r->>'subcategory_id',''), nullif(r->>'subcategory_name',''), nullif(r->>'subcategory_slug',''), nullif(r->>'focus_keyword',''), nullif(r->>'additional_keyword_1',''), nullif(r->>'additional_keyword_2',''), nullif(r->>'business_description',''), nullif(r->>'collection_id',''), nullif(r->>'status',''), coalesce(nullif(r->>'title',''), ir.title), nullif(r->>'summary',''), nullif(r->>'verdict',''), nullif(r->>'tier',''), coalesce(nullif(r->>'slug',''), ir.slug), coalesce(nullif(r->>'seo_title',''), ir.seo_title), coalesce(nullif(r->>'meta_description',''), ir.meta_description), nullif(r->>'market_opportunity',''), nullif(r->>'target_customer',''), nullif(r->>'how_you_make_money',''), nullif(r->>'startup_cost',''), nullif(r->>'income_potential',''), nullif(r->>'competition_edge',''), nullif(r->>'time_to_first_customer',''), (r->>'trend_score')::int, coalesce(r->'tags', ir.tags), r->'pros_json', r->'cons_json', r->'getting_started_steps', r->'tools_needed', r->'faq_json', coalesce(r->'external_links', ir.external_links), coalesce(r->'internal_link_anchors', ir.internal_link_anchors), coalesce(r->'research_facts', ir.research_facts)
from src left join public.idea_research ir on ir.idea_id = src.r->>'idea_id'
on conflict (idea_id) do nothing;